using System;using System.Globalization;using System.Text.RegularExpressions;
namespace BeamScheduleFormatter {
static class ColumnTieSchedule {
 internal static bool Looks(string text){double plain;if(string.IsNullOrWhiteSpace(text)||double.TryParse(text.Trim(),NumberStyles.Float,CultureInfo.InvariantCulture,out plain))return false;return Regex.IsMatch(text,@"\d+\s*-\s*\d+\s*mm",RegexOptions.IgnoreCase);}
 internal static int Count(string schedule,double height,double width,double depth,int diameter,double cover,LengthConfiguration cfg){string value=Regex.Replace((schedule??"").Replace("\r"," ").Replace("\n"," "),@"\(\s*\d+\s*TIES?\s*/\s*SET\s*\)","",RegexOptions.IgnoreCase).Trim();value=Regex.Replace(value,@"\s+"," ");value=Regex.Replace(value,@"(?<=\d)\s+mm","mm",RegexOptions.IgnoreCase);if(value.IndexOf("TO FREE END",StringComparison.OrdinalIgnoreCase)>=0)throw new Exception("TO FREE END is a beam cantilever schedule, not a column schedule.");var first=Regex.Match(value,@"^1\s*-\s*(\d+)mm",RegexOptions.IgnoreCase);if(!first.Success)throw new Exception("Column schedule example: 1 - 50mm, 11 - 75mm, AND REST AT 200mm C/C.");var row=new BeamRow{Mark="Column",Leg="2L",Diameter="O"+diameter,RevisedSpacing=value};row.Cells[0].Add(width.ToString(CultureInfo.InvariantCulture));row.Cells[1].Add(depth.ToString(CultureInfo.InvariantCulture));var result=new BeamEstimate();RevisedSchedule.AddTies(result,row,"Column",height,new EstimateOptions{LengthConfig=cfg,Cover=cover,Offset=int.Parse(first.Groups[1].Value,CultureInfo.InvariantCulture)},null,1);return result.Ties;}
}
}
